from itertools import product

factors = {
    "water_pct": (28, 34),
    "dry_temp_c": (55, 65),
    "comp_force_kn": (12, 18),
}
runs = list(product(*factors.values()))
for i, run in enumerate(runs, 1):
    print(i, dict(zip(factors, run)))
centre = {k: sum(v) / 2 for k, v in factors.items()}
print("centre point:", centre)

source = {"R1": ("0.50", "mg"), "R2": ("98.7", "%"), "R3": ("12", "ppm")}
target = {"R1": ("0.5", "mg"), "R2": ("98.7", "%")}
print("missing in target:", sorted(set(source) - set(target)))
for rid in sorted(set(source) & set(target)):
    if source[rid] != target[rid]:
        print("mismatch", rid, source[rid], "->", target[rid])
